import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JToolBar;

public class ToolBarComboPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        for (java.awt.Component c : root.getComponents()) {
            if (name.equals(c.getName())) {
                return c;
            }
            if (c instanceof java.awt.Container) {
                java.awt.Component found = find((java.awt.Container) c, name);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

    public static void main(String[] args) {
        try {
            ToolBarComboPanel panel = new ToolBarComboPanel();
            java.awt.Component t = find(panel, "toolbar");
            java.awt.Component c = find(panel, "combo");
            JComboBox<?> combo = c instanceof JComboBox ? (JComboBox<?>) c : null;

            check("a toolbar and a combo box exist", true,
                    t instanceof JToolBar && combo != null);

            panel.addTool("Bold");
            panel.addTool("Italic");
            java.awt.Component boldButton = find(panel, "Bold");

            check("two named buttons sit on the toolbar", "2/Bold", panel.toolCount() + "/"
                    + (boldButton instanceof JButton ? ((JButton) boldButton).getText() : "missing"));

            check("nothing is selected while the model is empty", null, panel.selectedFont());

            panel.addFont("Serif");
            check("the first element is auto-selected", "Serif", panel.selectedFont());

            panel.addFont("Sans");
            panel.addFont("Mono");
            panel.addFont("Serif");
            check("duplicates are ignored", 3, combo == null ? null : combo.getItemCount());

            check("selecting a present entry", "true/Sans",
                    panel.selectFont("Sans") + "/" + panel.selectedFont());
            check("selecting an absent entry leaves the selection alone", "false/Sans",
                    panel.selectFont("Comic") + "/" + panel.selectedFont());
            check("removing an entry, then removing it again", "true/2/false",
                    panel.removeFont("Mono") + "/" + (combo == null ? "?" : combo.getItemCount())
                            + "/" + panel.removeFont("Mono"));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

