import javax.swing.DefaultComboBoxModel;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JPanel;
import javax.swing.JToolBar;

public class ToolBarComboPanel extends JPanel {

    private final JToolBar toolBar = new JToolBar();
    private final DefaultComboBoxModel<String> fonts = new DefaultComboBoxModel<>();
    private final JComboBox<String> combo = new JComboBox<>(fonts);

    public ToolBarComboPanel() {
        toolBar.setName("toolbar");
        combo.setName("combo");
        add(toolBar);
        add(combo);
    }

    public void addTool(String label) {
        JButton button = new JButton(label);
        button.setName(label);
        toolBar.add(button);
    }

    public int toolCount() {
        int count = 0;
        for (java.awt.Component c : toolBar.getComponents()) {
            if (c instanceof JButton) {
                count++;
            }
        }
        return count;
    }

    public void addFont(String name) {
        if (fonts.getIndexOf(name) < 0) {
            fonts.addElement(name);
        }
    }

    public boolean selectFont(String name) {
        if (fonts.getIndexOf(name) < 0) {
            return false;
        }
        combo.setSelectedItem(name);
        return true;
    }

    public String selectedFont() {
        Object selected = combo.getSelectedItem();
        return selected == null ? null : selected.toString();
    }

    public boolean removeFont(String name) {
        if (fonts.getIndexOf(name) < 0) {
            return false;
        }
        fonts.removeElement(name);
        return true;
    }
}
